">SoundPrint</span>\n      </div>\n      <div class=\"security\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z\"/><path d=\"m9 12 2 2 4-4\"/></svg>\n        <span>Official secure password reset</span>\n      </div>\n\n      <section class=\"panel\" id=\"reset-panel\" aria-labelledby=\"page-heading\">\n        <div id=\"reset-content\">\n          <div class=\"status-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"10\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 10V7a5 5 0 0 1 10 0v3\"/><path d=\"M12 14v3\"/></svg>\n          </div>\n          <h1 id=\"page-heading\">Choose a new password</h1>\n          <p class=\"intro\">Set a new password for your SoundPrint account. Choose at least 8 characters.</p>\n\n          <form id=\"password-form\" class=\"form\" hidden>\n            <div class=\"field\">\n              <label for=\"new-password\">New password</label>\n              <div class=\"input-wrap\">\n                <input id=\"new-password\" name=\"new-password\" type=\"password\" autocomplete=\"new-password\" minlength=\"8\" placeholder=\"Enter your new password\" required>\n                <button id=\"show-password\" class=\"show-password\" type=\"button\" aria-label=\"Show password\">\n                  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>\n                </button>\n              </div>\n            </div>\n            <div class=\"field\">\n              <label for=\"confirm-new-password\">Confirm new password</label>\n              <input id=\"confirm-new-password\" name=\"confirm-new-password\" type=\"password\" autocomplete=\"new-password\" minlength=\"8\" placeholder=\"Enter it again\" required>\n            </div>\n            <p class=\"hint\">Use at least 8 characters. Make it unique to your SoundPrint account.</p>\n            <button id=\"submit-button\" class=\"button\" type=\"submit\" disabled>Update password</button>\n          </form>\n\n          <p id=\"waiting\" class=\"notice\" role=\"status\">Verifying your secure password-reset link…</p>\n          <p id=\"error-message\" class=\"notice error\" role=\"alert\" hidden></p>\n          <a id=\"request-link\" class=\"text-link\" href=\"soundprint://account\" hidden>Return to SoundPrint to request a new link</a>\n        </div>\n\n        <div id=\"success-content\" hidden>\n          <div class=\"success-mark\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m5 12 4 4L19 6\"/></svg>\n          </div>\n          <h1>Your password has been reset</h1>\n          <p class=\"success-copy\">Your SoundPrint password has been updated successfully.</p>\n          <p class=\"safe-close\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z\"/><path d=\"m9 12 2 2 4-4\"/></svg>\n            You can safely close this page.\n          </p>\n          <a class=\"button\" id=\"back-to-sign-in\" href=\"soundprint://account\" style=\"margin-top:26px\">Back to sign in</a>\n        </div>\n      </section>\n    </main>\n\n    <footer class=\"footer\">\n      You are on <strong>soundprint.anchorstuds.com</strong><br>\n      Your password is handled securely by SoundPrint.\n    </footer>\n  </div>\n\n  <script type=\"module\">\n    import { createClient } from \"https://esm.sh/@supabase/supabase-js@2.112.3\";\n\n    const config = __SUPABASE_CONFIG__;\n    const isNewApiKey = config.key.startsWith(\"sb_publishable_\") || config.key.startsWith(\"sb_secret_\");\n    const customFetch = (input, init) => {\n      const headers = new Headers(typeof Request !== \"undefined\" && input instanceof Request ? input.headers : undefined);\n      if (init && init.headers) new Headers(init.headers).forEach((value, key) => headers.set(key, value));\n      if (isNewApiKey && headers.get(\"Authorization\") === \"Bearer \" + config.key) headers.delete(\"Authorization\");\n      headers.set(\"apikey\", config.key);\n      return fetch(input, { ...init, headers });\n    };\n\n    const supabase = createClient(config.url, config.key, {\n      global: { fetch: customFetch },\n      auth: {\n        storage: window.localStorage,\n        persistSession: true,\n        autoRefreshToken: true,\n        flowType: \"pkce\"\n      }\n    });\n\n    const form = document.getElementById(\"password-form\");\n    const waiting = document.getElementById(\"waiting\");\n    const requestLink = document.getElementById(\"request-link\");\n    const errorMessage = document.getElementById(\"error-message\");\n    const passwordInput = document.getElementById(\"new-password\");\n    const confirmInput = document.getElementById(\"confirm-new-password\");\n    const showPasswordButton = document.getElementById(\"show-password\");\n    const submitButton = document.getElementById(\"submit-button\");\n    const resetContent = document.getElementById(\"reset-content\");\n    const successContent = document.getElementById(\"success-content\");\n    let busy = false;\n    let showPassword = false;\n    let recoveryReady = false;\n\n    const eyeIcon = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    const eyeOffIcon = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m3 3 18 18\"/><path d=\"M10.6 10.6a2 2 0 0 0 2.8 2.8\"/><path d=\"M9.9 5.2A11 11 0 0 1 12 5c6.4 0 10 7 10 7a16 16 0 0 1-4.1 4.8\"/><path d=\"M6.2 6.2A17 17 0 0 0 2 12s3.6 7 10 7c1.5 0 2.8-.4 4-1\"/></svg>';\n\n    function updateReadyState(ready) {\n      recoveryReady = ready;\n      waiting.hidden = ready;\n      form.hidden = !ready;\n      requestLink.hidden = ready;\n    }\n\n    function showError(message) {\n      errorMessage.textContent = message;\n      errorMessage.hidden = false;\n    }\n\n    function updateSubmitState() {\n      submitButton.disabled = busy || passwordInput.value.length < 8 || passwordInput.value !== confirmInput.value;\n    }\n\n    function setBusy(value) {\n      busy = value;\n      submitButton.textContent = value ? \"Updating password…\" : \"Update password\";\n      passwordInput.disabled = value;\n      confirmInput.disabled = value;\n      showPasswordButton.disabled = value;\n      updateSubmitState();\n    }\n\n    passwordInput.addEventListener(\"input\", updateSubmitState);\n    confirmInput.addEventListener(\"input\", updateSubmitState);\n\n    showPasswordButton.addEventListener(\"click\", () => {\n      showPassword = !showPassword;\n      passwordInput.type = showPassword ? \"text\" : \"password\";\n      confirmInput.type = showPassword ? \"text\" : \"password\";\n      showPasswordButton.setAttribute(\"aria-label\", showPassword ? \"Hide password\" : \"Show password\");\n      showPasswordButton.innerHTML = showPassword ? eyeOffIcon : eyeIcon;\n    });\n\n    supabase.auth.onAuthStateChange((event, session) => {\n      if (event === \"PASSWORD_RECOVERY\" && session) updateReadyState(true);\n    });\n\n    void supabase.auth.getSession().then(({ data, error }) => {\n      if (error) throw error;\n      const params = new URLSearchParams(window.location.search);\n      if (data.session && (params.has(\"code\") || params.get(\"recovery\") === \"1\")) {\n        updateReadyState(true);\n      } else if (!recoveryReady) {\n        waiting.textContent = \"This reset link is invalid or has expired. Return to SoundPrint to request a new one.\";\n        requestLink.hidden = false;\n      }\n    }).catch((error) => {\n      waiting.textContent = \"We couldn't verify this reset link.\";\n      showError(error instanceof Error ? error.message : \"Request a new password-reset link from SoundPrint.\");\n      requestLink.hidden = false;\n    });\n\n    form.addEventListener(\"submit\", async (event) => {\n      event.preventDefault();\n      errorMessage.hidden = true;\n      if (passwordInput.value.length < 8) {\n        showError(\"Choose a password with at least 8 characters.\");\n        return;\n      }\n      if (passwordInput.value !== confirmInput.value) {\n        showError(\"Your passwords don't match. Check both fields and try again.\");\n        return;\n      }\n\n      setBusy(true);\n      try {\n        const { error } = await supabase.auth.updateUser({ password: passwordInput.value });\n        if (error) throw error;\n\n        form.hidden = true;\n        resetContent.hidden = true;\n        successContent.hidden = false;\n        document.title = \"Password reset · SoundPrint\";\n        await supabase.auth.signOut({ scope: \"local\" }).catch(() => {});\n      } catch (error) {\n        showError(error instanceof Error\n          ? error.message\n          : \"We couldn't update your password. Request a new reset link and try again.\");\n      } finally {\n        if (successContent.hidden) setBusy(false);\n      }\n    });\n  </script>\n</body>\n</html>";

function redirect(location) {
  return new Response(null, {
    status: 302,
    headers: { Location: location, "Cache-Control": "no-store" }
  });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === "/") {
      return redirect(new URL("/reset-password" + url.search, url).toString());
    }
    if (url.pathname === "/auth" || url.pathname === "/auth/") {
      return redirect("soundprint://auth");
    }
    if (url.pathname === "/reset-password/") {
      return redirect(new URL("/reset-password" + url.search, url).toString());
    }
    if (url.pathname !== "/reset-password") {
      return new Response("Not found", {
        status: 404,
        headers: { "Content-Type": "text/plain; charset=utf-8" }
      });
    }
    if (request.method !== "GET" && request.method !== "HEAD") {
      return new Response("Method not allowed", {
        status: 405,
        headers: { Allow: "GET, HEAD", "Cache-Control": "no-store" }
      });
    }
    if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) {
      return new Response("Password reset is temporarily unavailable.", {
        status: 503,
        headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" }
      });
    }

    const config = JSON.stringify({
      url: env.SUPABASE_URL,
      key: env.SUPABASE_PUBLISHABLE_KEY
    }).replace(/</g, "\\u003c");
    const body = htmlTemplate.replace("__SUPABASE_CONFIG__", config);
    const supabaseOrigin = new URL(env.SUPABASE_URL).origin;
    const supabaseHost = new URL(env.SUPABASE_URL).host;
    const headers = new Headers({
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-store",
      "X-Content-Type-Options": "nosniff",
      "X-Frame-Options": "DENY",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
      "Content-Security-Policy":
        "default-src 'self'; base-uri 'none'; object-src 'none'; frame-ancestors 'none'; " +
        "script-src 'self' 'unsafe-inline' https://esm.sh; " +
        "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; " +
        "font-src 'self' https://fonts.gstatic.com data:; " +
        "img-src 'self' data:; connect-src 'self' " + supabaseOrigin + " wss://" + supabaseHost + ";"
    });

    return new Response(request.method === "HEAD" ? null : body, {
      status: 200,
      headers
    });
  }
};